# Lunar Konstruksi - Fase 6 Full Admin CMS UI
# Smart installer: adds CMS workspace on top of Phase 1-5 foundations.
# Run from repo root: powershell -ExecutionPolicy Bypass -File .\Apply_Lunar_Fase_6_Admin_CMS_UI.ps1

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Phase([string]$Message) { Write-Host "[FASE 6] $Message" -ForegroundColor Cyan }
function Fail-Phase([string]$Message) { Write-Host ""; Write-Host "[FASE 6] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $parent = Split-Path -Parent $Path
  if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}
function Decode([string]$Value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail-Phase "Jalankan script ini dari repository Git Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot
$branch = (& git branch --show-current).Trim()
$head = (& git rev-parse --short HEAD).Trim()
Write-Phase "Repo   : $repoRoot"
Write-Phase "Branch : $branch"
Write-Phase "HEAD   : $head"

$trackedStatus = & git status --porcelain --untracked-files=no
if ($LASTEXITCODE -ne 0) { Fail-Phase "Tidak bisa membaca git status." }
if ($trackedStatus) { Write-Host $trackedStatus; Fail-Phase "Ada perubahan TRACKED yang belum disimpan. Commit/stash dulu agar installer aman." }

$required = @(
  "package.json",
  "app/admin/(dashboard)/layout.tsx",
  "components/admin/sidebar.tsx",
  "cms/blocks/registry.ts",
  "features/content/content.registry.ts",
  "features/pages/page.types.ts",
  "features/navigation/navigation.types.ts",
  "features/site-settings/site-settings.types.ts",
  "features/public-site/server.ts",
  "features/leads/lead.types.ts",
  "features/leads/client.ts",
  "app/api/admin/cms/pages/route.ts",
  "app/api/admin/cms/blocks/route.ts",
  "app/api/admin/cms/modules/route.ts",
  "app/api/admin/cms/navigation/route.ts",
  "app/api/admin/cms/settings/route.ts",
  "app/api/admin/leads/route.ts"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) { Write-Host "[FASE 6] Prasyarat yang belum ada:" -ForegroundColor Yellow; $missing | ForEach-Object { Write-Host "  - $_" }; Fail-Phase "Pastikan Fase 1-5 sudah terpasang pada branch lokal ini." }

$package = Get-Content -LiteralPath "package.json" -Raw
foreach ($dependency in @("firebase", "lucide-react", "next", "react")) { if ($package -notmatch ('"' + [regex]::Escape($dependency) + '"')) { Fail-Phase "Dependency $dependency tidak ditemukan. Fase 6 tidak akan mengubah dependency." } }

if (Test-Path -LiteralPath "components/admin/cms/cms-dashboard.tsx") { Fail-Phase "Full Admin CMS UI sudah terdeteksi. Fase 6 tampaknya sudah pernah diterapkan." }

Write-Phase "Prasyarat aman. Menyiapkan Full Admin CMS UI..."
$payload = @{}
$payload["ADMIN_CMS_UI.md"] = ""
$payload["app/admin/(dashboard)/cms/content/page.tsx"] = "aW1wb3J0IHsgQ21zQ29udGVudEh1YiB9IGZyb20gIkAvY29tcG9uZW50cy9hZG1pbi9jbXMvY21zLWNvbnRlbnQtaHViIjsKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIENtc0NvbnRlbnRQYWdlKCkgewogIHJldHVybiA8Q21zQ29udGVudEh1YiAvPjsKfQo="
$payload["app/admin/(dashboard)/cms/layout.tsx"] = ""
$payload["app/admin/(dashboard)/cms/leads/[id]/page.tsx"] = ""
$payload["app/admin/(dashboard)/cms/leads/page.tsx"] = "aW1wb3J0IHsgQ21zTGVhZHNNYW5hZ2VyIH0gZnJvbSAiQC9jb21wb25lbnRzL2FkbWluL2Ntcy9jbXMtbGVhZHMtbWFuYWdlciI7CgpleHBvcnQgZGVmYXVsdCBmdW5jdGlvbiBDbXNMZWFkc1BhZ2UoKSB7CiAgcmV0dXJuIDxDbXNMZWFkc01hbmFnZXIgLz47Cn0K"
$payload["app/admin/(dashboard)/cms/media/page.tsx"] = "aW1wb3J0IHsgQ21zQ29udGVudEh1YiB9IGZyb20gIkAvY29tcG9uZW50cy9hZG1pbi9jbXMvY21zLWNvbnRlbnQtaHViIjsKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIENtc01lZGlhUGFnZSgpIHsKICByZXR1cm4gPENtc0NvbnRlbnRIdWIgbWVkaWFPbmx5IC8+Owp9Cg=="
$payload["app/admin/(dashboard)/cms/navigation/page.tsx"] = "aW1wb3J0IHsgQ21zTmF2aWdhdGlvbk1hbmFnZXIgfSBmcm9tICJAL2NvbXBvbmVudHMvYWRtaW4vY21zL2Ntcy1uYXZpZ2F0aW9uLW1hbmFnZXIiOwoKZXhwb3J0IGRlZmF1bHQgZnVuY3Rpb24gQ21zTmF2aWdhdGlvblBhZ2UoKSB7CiAgcmV0dXJuIDxDbXNOYXZpZ2F0aW9uTWFuYWdlciAvPjsKfQo="
$payload["app/admin/(dashboard)/cms/page.tsx"] = "aW1wb3J0IHsgQ21zRGFzaGJvYXJkIH0gZnJvbSAiQC9jb21wb25lbnRzL2FkbWluL2Ntcy9jbXMtZGFzaGJvYXJkIjsKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIENtc0Rhc2hib2FyZFBhZ2UoKSB7CiAgcmV0dXJuIDxDbXNEYXNoYm9hcmQgLz47Cn0K"
$payload["app/admin/(dashboard)/cms/pages/[id]/page.tsx"] = ""
$payload["app/admin/(dashboard)/cms/pages/page.tsx"] = "aW1wb3J0IHsgQ21zUGFnZXNNYW5hZ2VyIH0gZnJvbSAiQC9jb21wb25lbnRzL2FkbWluL2Ntcy9jbXMtcGFnZXMtbWFuYWdlciI7CgpleHBvcnQgZGVmYXVsdCBmdW5jdGlvbiBDbXNQYWdlc1BhZ2UoKSB7CiAgcmV0dXJuIDxDbXNQYWdlc01hbmFnZXIgLz47Cn0K"
$payload["app/admin/(dashboard)/cms/settings/page.tsx"] = "aW1wb3J0IHsgQ21zU2V0dGluZ3NNYW5hZ2VyIH0gZnJvbSAiQC9jb21wb25lbnRzL2FkbWluL2Ntcy9jbXMtc2V0dGluZ3MtbWFuYWdlciI7CgpleHBvcnQgZGVmYXVsdCBmdW5jdGlvbiBDbXNTZXR0aW5nc1BhZ2UoKSB7CiAgcmV0dXJuIDxDbXNTZXR0aW5nc01hbmFnZXIgLz47Cn0K"
$payload["app/api/admin/cms/revalidate/route.ts"] = ""
$payload["components/admin/cms/cms-api.ts"] = ""
$payload["components/admin/cms/cms-content-hub.tsx"] = ""
$payload["components/admin/cms/cms-dashboard.tsx"] = ""
$payload["components/admin/cms/cms-lead-editor.tsx"] = ""
$payload["components/admin/cms/cms-leads-manager.tsx"] = ""
$payload["components/admin/cms/cms-navigation-manager.tsx"] = ""
$payload["components/admin/cms/cms-page-editor.tsx"] = ""
$payload["components/admin/cms/cms-pages-manager.tsx"] = ""
$payload["components/admin/cms/cms-settings-manager.tsx"] = ""
$payload["components/admin/cms/cms-ui.tsx"] = ""
$payload["components/admin/cms/cms-workspace-nav.tsx"] = ""

foreach ($entry in $payload.GetEnumerator()) {
  $target = Join-Path $repoRoot $entry.Key
  Write-Utf8NoBom $target (Decode $entry.Value)
  Write-Host "[FASE 6] write  $($entry.Key)" -ForegroundColor DarkGray
}

# Optional, low-risk discovery bridge: add a plain CMS Workspace entry into the first <nav> of the existing admin sidebar.
$sidebarPath = Join-Path $repoRoot "components/admin/sidebar.tsx"
$sidebar = [System.IO.File]::ReadAllText($sidebarPath)
if ($sidebar -notmatch 'data-lunar-cms-entry="true"') {
  $match = [System.Text.RegularExpressions.Regex]::Match($sidebar, '<nav\b[^>]*>', [System.Text.RegularExpressions.RegexOptions]::Singleline)
  if ($match.Success) {
    $nl = if ($sidebar.Contains("`r`n")) { "`r`n" } else { "`n" }
    $launcher = $nl + '        <a data-lunar-cms-entry="true" href="/admin/cms" className="mb-3 flex items-center justify-between rounded-xl border border-black/10 bg-black px-3 py-2.5 text-sm font-semibold text-white transition hover:bg-zinc-800">' + $nl + '          <span>CMS Workspace</span><span aria-hidden="true">↗</span>' + $nl + '        </a>'
    $sidebar = $sidebar.Substring(0, $match.Index + $match.Length) + $launcher + $sidebar.Substring($match.Index + $match.Length)
    Write-Utf8NoBom $sidebarPath $sidebar
    Write-Host "[FASE 6] patch  components/admin/sidebar.tsx (CMS entry)" -ForegroundColor Green
  } else {
    Write-Host "[FASE 6] info   Sidebar tidak memiliki <nav>; entry tidak diinjeksi. Workspace tetap tersedia di /admin/cms." -ForegroundColor Yellow
  }
}

Write-Host ""
Write-Host "[FASE 6] Full Admin CMS UI selesai diterapkan." -ForegroundColor Green
Write-Host "[FASE 6] Workspace: http://localhost:3000/admin/cms" -ForegroundColor Green
Write-Host "[FASE 6] Tidak ada dependency baru; npm install tidak diperlukan." -ForegroundColor Green
Write-Host ""
Write-Host "Validasi berikutnya:" -ForegroundColor Cyan
Write-Host "  npm run lint"
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  git diff --check"
Write-Host "  git status --short"
